// Generated by esquadro: do not edit. The trash of a resource whose entity
// has one (@store(soft_delete)): deleting asks less and can be undone, and
// the trash lists what went there, to restore or delete for good.
import { keepPreviousData, useMutation, useQuery, useQueryClient, type QueryClient } from "@tanstack/react-query"
import { useNavigate, useSearch } from "@tanstack/react-router"
import { ArrowLeft, ChevronLeft, ChevronRight, RotateCcw, Trash2 } from "lucide-react"
import { toast as sonner } from "sonner"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { isApiError } from "@api"
import { api } from "../api.ts"
import { ask } from "./confirm.tsx"
import { describe } from "./errors.ts"
import { format, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta, TrashApi } from "./meta.ts"
import { PageHeader } from "./page.tsx"
import type { Resource } from "./resource.ts"
import { StateView } from "./states.tsx"
import { toast } from "./toast.tsx"

const PER_PAGE = 20

/**
 * Why a record could not come back, in words: what it points at is in the
 * trash too, or another took one of its unique values meanwhile.
 */
export function restoreProblem(meta: ResourceMeta, e: unknown): string {
  if (isApiError(e) && e.code === "invalid_fields" && e.fields[0]) {
    const f = e.fields[0]
    const field = meta.fields[f.field] ?? meta.fields[`${f.field}_id`]
    const name = (field?.label ?? f.field).toLocaleLowerCase()
    if (f.code === "in_trash") return t("restoreParentInTrash", { name })
    if (f.code === "taken") return t("restoreTaken", { name })
  }
  return describe(e)
}

/** The trash of a resource: undefined when deleting removes for good. */
export function trashOf(meta: ResourceMeta): TrashApi | undefined {
  return meta.trash ? meta.api(api as never).trash : undefined
}

/** Asks before deleting: putting in the trash, or deleting for good. */
export function confirmRemove(meta: ResourceMeta, count = 1): Promise<boolean> {
  if (meta.trash) {
    return ask(count > 1 ? t("trashManyQ", { count }) : t("trashQ"), { description: t("trashHint"), confirm: t("moveToTrash") })
  }
  return ask(count > 1 ? t("confirmDeleteMany", { count }) : t("confirmDelete"), {
    destructive: true,
    description: t("cantUndo"),
    confirm: t("delete"),
  })
}

/** Tells a record was deleted: in the trash, with Undo, when it has one. */
export function removed(meta: ResourceMeta, record: Rec, queryClient: QueryClient): void {
  const trash = trashOf(meta)
  if (!trash) return toast(t("deleted"))
  sonner.success(t("trashed"), {
    // Long enough to change one's mind.
    duration: 8000,
    action: {
      label: t("undo"),
      onClick: async () => {
        try {
          await trash.restore(record.id)
          toast(t("restored"))
        } catch (e) {
          toast(restoreProblem(meta, e), "error")
        }
        queryClient.invalidateQueries({ queryKey: [meta.name] })
      },
    },
  })
}

/** How many records the trash holds, for its button; undefined without one. */
export function useTrashCount(meta: ResourceMeta, enabled = true): number | undefined {
  const trash = trashOf(meta)
  const count = useQuery({
    queryKey: [meta.name, "trash", "count"],
    queryFn: () => trash!.list({ page: 1, per_page: 1 }),
    enabled: Boolean(trash) && enabled,
    staleTime: 30_000,
  })
  return count.data?.total
}

/** When a record went to the trash, as a date and time. */
const deletedAt: FieldMeta = { name: "deleted_at", label: "", kind: "datetime", required: true }

/** The trash of a resource: what went there, to restore or delete for good. */
export function TrashList({ resource }: { resource: Resource }) {
  const { meta } = resource
  const trash = trashOf(meta)!
  const search = useSearch({ strict: false }) as { page?: number }
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const page = Number(search.page) || 1
  const list = useQuery({
    queryKey: [meta.name, "trash", page],
    queryFn: () => trash.list({ page, per_page: PER_PAGE }),
    placeholderData: keepPreviousData,
  })
  const act = useMutation({
    mutationFn: (run: () => Promise<unknown>) => run(),
    onSettled: () => queryClient.invalidateQueries({ queryKey: [meta.name] }),
    onError: (e) => toast(restoreProblem(meta, e), "error"),
  })
  const title = meta.fields[resource.title?.name ?? meta.title] as FieldMeta | undefined
  const name = (r: Rec) => (title ? format(title, r[title.name]) : r.id)
  const items = list.data?.items ?? []
  const totalPages = list.data?.total_pages ?? 0
  const back = () => navigate({ to: ".", search: {} as never })
  const days = meta.trash?.days ?? 0

  return (
    <div className="flex flex-col gap-4 rounded-xl border border-border bg-card p-5">
      <PageHeader
        title={t("trashOf", { name: meta.label })}
        description={days > 0 ? t("trashDaysHint", { days }) : t("trashKeptHint")}
        actions={
          <>
            <Button variant="outline" onClick={back}>
              <ArrowLeft /> {meta.label}
            </Button>
            {items.length > 0 && (
              <Button
                variant="destructive-outline"
                disabled={act.isPending}
                onClick={async () => {
                  if (!(await ask(t("emptyTrashQ"), { destructive: true, description: t("emptyTrashHint"), confirm: t("emptyTrash") }))) return
                  act.mutate(() => trash.empty().then((r) => toast(t("purgedCount", { count: r.purged }))))
                }}
              >
                <Trash2 /> {t("emptyTrash")}
              </Button>
            )}
          </>
        }
      />
      {list.isSuccess && items.length === 0 ? (
        <StateView icon={<Trash2 />} title={t("trashEmpty")} description={t("trashEmptyHint")} />
      ) : (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{title?.label ?? meta.singular}</TableHead>
              <TableHead className="text-xs font-semibold tracking-wider text-muted-foreground uppercase">{t("deletedAt")}</TableHead>
              <TableHead className="w-0" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {list.isPending &&
              Array.from({ length: 5 }, (_, i) => (
                <TableRow key={i}>
                  <TableCell colSpan={3}>
                    <Skeleton className="h-8 w-full" />
                  </TableCell>
                </TableRow>
              ))}
            {items.map((r) => (
              <TableRow key={r.id}>
                <TableCell className="font-semibold text-foreground">{name(r)}</TableCell>
                <TableCell className="text-muted-foreground">{format(deletedAt, r.deleted_at)}</TableCell>
                <TableCell>
                  <div className="flex justify-end gap-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      disabled={act.isPending}
                      onClick={() => act.mutate(() => trash.restore(r.id).then(() => toast(t("restored"))))}
                    >
                      <RotateCcw /> {t("restore")}
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-destructive hover:text-destructive"
                      disabled={act.isPending}
                      onClick={async () => {
                        if (!(await ask(t("purgeQ", { name: name(r) }), { destructive: true, description: t("cantUndo"), confirm: t("deleteForGood") }))) return
                        act.mutate(() => trash.purge(r.id).then(() => toast(t("deleted"))))
                      }}
                    >
                      <Trash2 /> {t("deleteForGood")}
                    </Button>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}
      {totalPages > 1 && (
        <div className="flex items-center justify-end gap-1 text-sm">
          <Button
            variant="ghost"
            size="icon-sm"
            disabled={page <= 1}
            aria-label={t("previous")}
            onClick={() => navigate({ to: ".", search: (s: Record<string, unknown>) => ({ ...s, page: page - 1 }) as never })}
          >
            <ChevronLeft />
          </Button>
          <span className="px-2 font-semibold tabular-nums">
            {page} / {totalPages}
          </span>
          <Button
            variant="ghost"
            size="icon-sm"
            disabled={page >= totalPages}
            aria-label={t("next")}
            onClick={() => navigate({ to: ".", search: (s: Record<string, unknown>) => ({ ...s, page: page + 1 }) as never })}
          >
            <ChevronRight />
          </Button>
        </div>
      )}
    </div>
  )
}
